  ('70051', 'הנדסת תעשייה וניהול טכנולוגיה', 'פרויקט גמר בהנדסת תעשייה וניהול טכנלוגיה', 4, 'סמסטר א׳', 3, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-nahat/'),
