  ('70090', 'הנדסת תעשייה וניהול טכנולוגיה', 'מערכות מידע ארגוניות', 4, 'סמסטר ב׳', 3.5, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-nahat/'),
  ('70096', 'הנדסת תעשייה וניהול טכנולוגיה', 'דיני עסקים וקניין רוחני', 4, 'סמסטר ב׳', 3.5, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-nahat/'),
  ('13127', 'טכנולוגיות למידה', 'מידענות ואוריינות מידע בסביבת האינטרנט', 1, 'סמסטר א׳', 2, 'לאתר, להעריך ולהצליב מידע מתוך מגוון מקורות בסביבות דיגיטליות שונות לצורכי מחקר, פיתוח ותכנון פרויקטים. לאתר חומרים טקסטואליים ושאינם טקסטואליים, במגוון מנועי חיפוש ולהעריך את איכותם. להכיר וללמוד גישות חדשות ומעודכנות לאוריינות מידע אצל משתמשים בעלי מאפיינים שונים. להכיר וללמוד תוכנות שונות לניהול חומרים ומידע אקדמי לאחזור, שמירה וקטלוג באופן עצמאי. לפתח ולחזק תודעת שימוש בכלים דיגיטליים עדכניים תוך מתן חשיבות לכללים, לחוקים ולהבנת הלוגיקה מאחורי המערכות שאנו פועלים בהן ביום-יום.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13135', 'טכנולוגיות למידה', 'שיטות מחקר במדעי החברה 1', 1, 'סמסטר א׳', 2, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13145', 'טכנולוגיות למידה', 'מבוא לבינה מלאכותית יוצרת וחווית משתמש', 1, 'סמסטר א׳', 3, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13149', 'טכנולוגיות למידה', 'ללמוד איך ללמוד באקדמיה', 1, 'סמסטר א׳', 1, 'ירכשו הבנה של מאפייני הלמידה באקדמיה ובפקולטה לטכנולוגיות למידה ירכשו מיומנויות ללמידה שיתופית ועבודה בצוות יפתחו חוסן בלמידה אקדמית יפתחו אוריינות אקדמית יפתחו מיומנויות איתור מקורות וכתיבה באקדמיה', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13203', 'טכנולוגיות למידה', 'החוק, תקשוב וקניין רוחני', 1, 'סמסטר א׳', 2, 'ההתפתחות הטכנולוגית המואצת מעלה דילמות משפטיות חדשות והופכת את ההגנה על נכסים לא מוחשיים לצורך הכרחי ולידע חיוני לעוסקים בתחומי הניהול והטכנולוגיה. הקורס יבחן את סוגיית הקניין הרוחני תוך התמקדות בשלושה תחומים מרכזיים: דיני פטנטים, סימני מסחר וזכויות יוצרים. כמו כן נדון בהיבטים של קניין רוחני הבאים לידי ביטוי במחשבים ובטכנולוגיות מתקדמות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13204', 'טכנולוגיות למידה', 'התנהגות ארגונית', 1, 'סמסטר א׳', 2, 'מושגי יסוד בהתנהגות ארגונית והקשר ביניהם. האסכולות המרכזיות בתחום התנהגות ארגונית. להסביר תיאוריות ניהוליות המסייעות להבנת המשאב האנושי במסגרת הארגונית. מתודולוגיה ניסויית בחקר ארגונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13219', 'טכנולוגיות למידה', 'יסודות החשיבה החישובית', 1, 'סמסטר א׳', 2, 'הקורס מוביל את הסטודנטים דרך תהליך הכולל רכישת מיומנויות בסיסיות ומורכבות בחשיבה לוגית ובאלגוריתמיקה הנדרשת לפיתוח מערכות טכנולוגיות ללמידה ולהדרכה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13302', 'טכנולוגיות למידה', 'מבוא לסביבות אינטראקטיביות', 1, 'סמסטר א׳', 2, 'הכרת מושגים ועקרונות בהקשר לסביבות אינטראקטיביות ממוחשבות. הכרת מיפויים ואפיונים של ממדי אינטראקציה בממשק והשימושים בהם למטרות שונות. פיתוח יכולת לתעד, לאפיין ולנתח סביבה אינטראקטיבית על פי מאפיינים, מטרות ושימושים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13303', 'טכנולוגיות למידה', 'גרפיקה ממוחשבת ( A )', 1, 'סמסטר א׳', 1, 'הכרות עם מושגי יסוד מעולם הגרפיקה והעיצוב במטרה ליצור אלמנטים, קומפוזיציות וממשקים ויזואליים תוך כדי שימוש והכרת Adobe Photoshop.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13319', 'טכנולוגיות למידה', 'תקשורת חזותית ( A )', 1, 'סמסטר א׳', 2, 'פיתוח יכולת התבוננות ויצירת פרשנות לדימויים חזותיים . הכרות ראשונית עם אלמנטים מעולם העיצוב והבניית דימויים חזותיים חדשים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13412', 'טכנולוגיות למידה', 'פרזנטציות אפקטיביות', 1, 'סמסטר א׳', 2, 'תכנון, עיצוב והצגה של פרזנטציות הם חלק משגרת העבודה של ''עובדי ידע'' בארגונים לומדים. בכלכלה גלובלית ותחרותית לפרזנטציה בת מספר דקות בודדות עשויה להיות השפעה מכרעת על גורל של ארגון. יתר-על כן, אחד התפקידים של אנשי הדרכה הוא לסייע למנהלים בארגונים לתכנן פרזנטציות אפקטיביות וללוות אותם במהלך הפיתוח של מיומנויות הפרזנטציה שלהם. מטרת הקורס להקנות מיומנויות ששילוב ביניהן יוביל להצגה של פרזנטציות מאורגנות היטב, רלוונטיות, הגיוניות, מהנות, וסוחפות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13116', 'טכנולוגיות למידה', 'ארגון וייצוג ידע ( B )', 1, 'סמסטר ב׳', NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13119', 'טכנולוגיות למידה', 'הנגשת אתרי אינטרנט ( C )', 1, 'סמסטר ב׳', NULL, 'הכרת נושא שוויון זכויות לאנשים עם מוגבלות ונגישות בהקשרם הערכי, החברתי והחוקי וכן הכרת צרכים מיוחדים של אנשים עם מוגבלות בשימושי באינטרנט ובסמרטפונים. הכרת התקן הטכניקות לפיתוח אתרים נגישים לאנשים עם מוגבלות ואופן בחינת נגישות אתרים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13136', 'טכנולוגיות למידה', 'שיטות מחקר במדעי החברה 2', 1, 'סמסטר ב׳', NULL, 'שני חלקי קורס זה מיועדים להקנות לסטודנטים ידע, מיומנויות וערכים בנושא המחקר הכמותי במדעי החברה וההתנהגות וכן מושגים וכלים ראשוניים מתחום הסטטיסטיקה התיאורית וההיסקית. הקורס מקנה שיטות וכלים לתכנון, ביצוע והצגת מחקרים במגוון שיטות מחקר. במסגרת הקורסים ירכשו הסטודנטים כלים מושגיים וטכניים להצגת נתונים, עיבודם וניתוחם. הקורסים מתמקדים במחקרים הרלוונטיים לסטודנטים הלומדים בפקולטה לטכנולוגיות למידה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13144', 'טכנולוגיות למידה', 'פסיכולוגיה ולמידה', 1, 'סמסטר ב׳', NULL, 'הכרות עם אופני החשיבה, המחקר והמתודולוגיה של פסיכולוגיה הכרות והבנה של התיאוריות פסיכולוגיות העוסקות בהתפתחות, מוטיבציה, למידה והוראה יכולת ליישם תיאוריות למידה ביהביוריסטיות, קוגניטיביסטיות וקונסטרוקטיביסטיות בניתוח ועיצוב של תוצרי למידה מהי פסיכולוגיה? פרספקטיבה התפתחותית מוטיבציה: תנאי קדם ללמידה הערכה עצמית ומוטיבציה למידת מיומנויות פשוטות (ביהביוריזם) למידה והתפתחות קוגניטיבית זיכרון עבודה ותהליכי עיבוד מידע (קוגניטיביזם) זיכרון ארוך טווח חישה, תפיסה וקשב למידה של מושגים – אבני הבניין של החשיבה תיאוריית סכימות ולמידה העברה של למידה, למידה של עקרונות ושל מודלים מנטליים (קונסטרוקטיביזם)', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13206', 'טכנולוגיות למידה', 'מבוא לבסיסי נתונים', 1, 'סמסטר ב׳', NULL, 'הכרת העקרונות הנדרשים לצורך עבודה על בסיסי הנתונים יחסיים. בניית בסיסי נתונים הנדרשים לעולם מערכות הלמידה וההדרכה וניהולם באמצעות תכנות בשפת SQL.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13207', 'טכנולוגיות למידה', 'מבוא לתכנות ( D )', 1, 'סמסטר ב׳', NULL, 'הקורס יקנה לסטודנטים הכרה ועקרונות יסוד בעולם התכנות תוך שילוב מיומנויות חשיבה חישובית ואלגוריתמית.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13224', 'טכנולוגיות למידה', 'יסודות אפיון ופיתוח יחידות למידה', 1, 'סמסטר ב׳', NULL, 'הקניית מיומנויות בסיס בפיתוח תוכן הדרכתי ממוקד (מיקרו למידה). הקניית תשתית מושגית, תיאורטית ומעשי לאשכול קורסי פיתוח ההדרכה של התואר ראשון.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13304', 'טכנולוגיות למידה', 'פיתוח אתרי אינטרנט ( D )', 1, 'סמסטר ב׳', NULL, 'הכרות עם טכנולוגיות המשמשות לבניית אתרי אינטרנט. הקורס יציג עקרונות בסיסיים לעיצוב אתר אינטראקטיבי לימודי, פיתוח מיומנות לשימוש בשפות תגים ובתוכנות שונות לעיצוב, עימוד אתרים ושילוב מולטימדיה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13315', 'טכנולוגיות למידה', 'עיצוב ממשק משתמש ( C )', 1, 'סמסטר ב׳', NULL, 'הכרת עקרונות היסוד בעיצוב גראפי המתואם למטרות, לגודל מסך משתנה ולמדיות שונות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13316', 'טכנולוגיות למידה', 'אפיון ממשק וחווית משתמש ( C )', 1, 'סמסטר ב׳', NULL, 'היכרות עם עקרונות של שימושיות (Usability), הכרת תהליך האפיון ועיצוב חוויית שימוש (User Experience) בדגש על ממשקי אינטרנט, פיתוח ביקורתיות כלפי ממשקי משתמש (User Interface), באתרים, התנסות בתהליך אפיון ועיצוב של אתר אינטרנט וביצירת אלמנטים ויזואליים מתאימים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13318', 'טכנולוגיות למידה', 'מבוא לתכנות אינטראקציה ואנימציה ( B )', 1, 'סמסטר ב׳', NULL, 'הכרת שיטות וכלים ראשוניים ליצירת יישומי מולטימדיה בתוכנת adobe animate והתנסות בהפקת אנימציה ליניארית ואינטראקטיבית, מותאמת לסביבת האינטרנט.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13124', 'טכנולוגיות למידה', 'סביבות לימוד אינטראקטיביות 1 ( E )', 2, 'סמסטר א׳', 3, 'הכרת מושגים ועקרונות בהקשר לסביבות לימוד אינטראקטיביות. הכרת הפוטנציאל הייחודי שמציע התקשוב להוראה וללמידה וגישות שונות לניצול ולשילוב סביבות אינטראקטיביות בהוראת תחומי-תוכן שונים, ולמטרות שונות. התנסות בהערכת סביבת לימוד אינטראקטיבית. התנסות באפיון סביבת לימוד אינטראקטיבית.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13125', 'טכנולוגיות למידה', 'טכנולוגיות למידה עכשווית', 2, 'סמסטר א׳', 2, 'במהלך הקורס הסטודנטים: יכירו יתרונות וחסרונות בטכנולוגיות למידה שכיחות בדגש על יישומם בארגון. יבצעו התאמה בין צורך הדרכתי לבין טכנולוגיה אפשרית כמענה לצורך זה. יתרגלו מתודה לבחינה ביקורתית של כלים חדשים לקראת אימוץ אפשרי בארגון.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13130', 'טכנולוגיות למידה', 'תכנות אינטראקציה ואנימציה 1 ( E )', 2, 'סמסטר א׳', 3, 'הכרת עקרונות בפיתוח ממשקים אינטראקטיביים מבוססים על סביבת פיתוח Adobe Animate CC . הקניית יכולות פיתוח סביבות מולטימדיה אינטראקטיבית מבוססות קוד בצד לקוח.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13134', 'טכנולוגיות למידה', 'מחקר איכותני בטכנולוגיות וחווית למידה', 2, 'סמסטר א׳', 2, 'הקורס יעסוק בהכרת המחקר האיכותני בהקשר של חווית למידה ומשתמש בטכנולוגיות למידה. במהלך הקורס נעסוק בהגדרת שדה המחקר האיכותני, בהקשרו לחוויית למידה ומשתמש. נלמד על מתודות מרכזיות המשמשות לצורך הערכה איכותנית של חווית למידה ומשתמש. נדון ביתרונות ומגבלות של כל מתודה- וניישמן בתוך תרגולים. לבסוף נתייחס להיבטים אתיים של מחקר זה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13137', 'טכנולוגיות למידה', 'פיתוח הדרכה בארגון 1', 2, 'סמסטר א׳', 2, 'המטרה הכוללת של שני הקורסים היא להקנות לבוגר יכולת לתכנן ולפתח בצורה שיטתית אירוע הדרכה בסביבה ארגונית. מטרות הקורס הן: להקנות לבוגרים יכולות לכתוב דו"ח ניתוח צרכים, לבחור את תכני אירוע ההדרכה, לכתוב תרחיש הסמכה ולתכנן בדיקות הסמכה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13146', 'טכנולוגיות למידה', 'UX/UI* בעידן הבינה המלאכותית היוצרת', 2, 'סמסטר א׳', 2, 'בינה מלאכותית יוצרת (GenAI) משפרת את העבודה של מעצבי ux/ui, אך התהליך העיצובי האנושי (המסורתי) נדרש במקומות שבהם נדרשת הבנה רגשית, יצירתיות, גמישות ויכולת לפענח את הקשרי העיצוב הדינמיים והאישיים של המשתמש. מטרת הקורס הוא פיתוח תפיסת עולם כמעצבי.ות ux/ui לטכנולוגיות למידה דרך הצבת שאלות על שילוב genai כחלק מארגז הכלים של המעצב.ת או שינוי תפקיד המעצב.ת לאור הטכנולוגיה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13208', 'טכנולוגיות למידה', 'תכנות 1', 2, 'סמסטר א׳', 3, 'הכרת עקרונות של שפות תכנות צד לקוח/שרת (Full Stack) מונחות אירועים ועצמים ויישומיהם בסביבת WEB על בסיס טכנולוגית NET Web API.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13225', 'טכנולוגיות למידה', 'עיצוב גרפי לממשקים אינטראקטיביים', 2, 'סמסטר א׳', 2, 'מטרת הקורס הקניית יכולות עיצוב ממשקים אינטראקטיביים תוך התייחסות למאפיינים הייחודיים של ממשקים אילו. נכיר עקרונות עיצוב שפה ויזואלית לממשקים אינטראקטיביים ונתנסה ביצירת שפה ויזואלית. נכיר כלים ייעודיים ונפתח טכניקות בכלים אילו. נתנסה ביצירת אלמנטים גרפיים לממשקים אינטראקטיביים וביצירת אב- טיפוס בעל שפה חזותית עשירה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13338', 'טכנולוגיות למידה', 'פיתוח יחידות למידה דיגיטליות 1', 2, 'סמסטר א׳', 2, 'התנסות בפיתוח יחידות למידה דיגיטליות – פיתוח תוצרי למידה ברמת קושי עולה ובכלים דיגיטליים שונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13417', 'טכנולוגיות למידה', 'סמינריון 1', 2, 'סמסטר א׳', 2, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13122', 'טכנולוגיות למידה', 'סביבות לימוד אינטראקטיביות 2 ( F )', 2, 'סמסטר ב׳', 2, 'התנסות באפיון מחולל לסביבת לימוד אינטראקטיבית תוך יישום עקרונות שנלמדו בקורס סביבות למידה אינטראקטיביות 1 13124.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13131', 'טכנולוגיות למידה', 'תכנות אינטראקציה ואנימציה 2 ( F )', 2, 'סמסטר ב׳', 2, 'פיתוח ממשק אינטראקטיבי והנפשתי בשילוב קוד מבוסס צד לקוח מבוסס על JavaScript. הקניית מיומנות תקשורת עם סביבות ניהול מבוססות צד שרת דרך מבני נתונים כמו XML ו-JSON. הכרת עקרונות בעיצוב גרפי למשחקים ולסביבות לימוד אינטראקטיביות. הקניית יכולות פיתוח בסביבת Adobe Animate CC בעזרת קוד מבוסס צד לקוח', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13133', 'טכנולוגיות למידה', 'הוראה מתוקשבת – תיאוריה ויישום', 2, 'סמסטר ב׳', 2, 'הכרת מגוון גישות לפיתוח ויישום פעילויות לימודיות בסביבה מתוקשבת ובקורסי MOOC (Massive Open Online courses), דיון בפוטנציאל, במגבלות ובדרכים לשילוב פעילויות מתוקשבות בתכניות לימודים בתחומי תוכן שונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13138', 'טכנולוגיות למידה', 'פיתוח הדרכה בארגון 2', 2, 'סמסטר ב׳', 2, 'המטרה הכוללת של שני הקורסים היא להקנות לבוגר יכולת לתכנן ולפתח בצורה שיטתית אירוע הדרכה בסביבה ארגונית. מטרות הקורס הן: להקנות לבוגרים יכולות לכתוב מסמך תכנון הדרכה, להגן דידקטית על החלטות בפיתוח חומרי הדרכה ולקבל החלטות כיצד להעריך את אירוע ההדרכה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13139', 'טכנולוגיות למידה', 'מדידה והערכת למידה בעידן הדיגיטלי', 2, 'סמסטר ב׳', 2, 'הקנייה ידע תאורטי ומעשי ב: פרדיגמות שונות בתחום מדידה והערכה של למידה. פיתוח פריטי מבחן סגורים ופתוחים. דרכים למדידת מהימנות ותוקף של מבחנים. כלים חלופיים למדידה והערכה בסביבות דיגיטליות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13211', 'טכנולוגיות למידה', 'תכנות 2 ( F )', 2, 'סמסטר ב׳', 3, 'המשך הכרת עקרונות של שפות תכנות צד לקוח/שרת (Full Stack) מונחות אירועים ועצמים ויישומיהם בסביבת WEB על בסיס טכנולוגית .NET Web API נעסוק בעבודה מתקדמת שמשלבת טפסים, מודלי נתונים ובסיסי נתונים. נושאים עבודה מתקדמת עם Blazor ליצירת ממשקי משתמש עשירים עבודה עם טבלאות מרובות ובסיסי נתונים מורכבים שילוב רכיבי UI חיצוניים בצד שלישי בניית סביבת Full Stack לצורך תמיכה והעצמת תהליכי למידה והדרכה פרויקט הקורס משולב עם קורסים 13122 (אפיון) ו-13123 (פיתוח צד לקוח).', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13339', 'טכנולוגיות למידה', 'פיתוח יחידות למידה דיגיטליות 2', 2, 'סמסטר ב׳', 3, 'התנסות בפיתוח יחידות למידה דיגיטליות – החל ממיפוי התוכן, דרך גיבוש החוויה ("פיצוח"), בחירת הטכנולוגיות המתאימות לפיתוח התוצר הדיגיטלי, פיתוח תסריט מלא של לומדה והפקה בפועל של יחידת הלמידה באמצעות הכלים הטכנולוגיים שנבחרו.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13418', 'טכנולוגיות למידה', 'סמינריון 2', 2, 'סמסטר ב׳', 2, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13444', 'טכנולוגיות למידה', 'פיתוח והפקה של וידאו ללמידה', 2, 'סמסטר ב׳', 2, 'הקניית מיומנויות בסיס בפיתוח והפקת וידאו לימודי מקביעת הקונספט עד יצירת תוצר וידאו מוגמר תוך המשגה והתנסות בפיצוח, תסריטאות, ליווי יום צילום ועריכה של סרטון לימודי.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13132', 'טכנולוגיות למידה', 'פתרונות הדרכה הלכה למעשה', 3, 'סמסטר א׳', 2, 'הקורס הינו קורס אינטגרטיבי אשר מטרותיו הן תמצות הידע והיכולות שהסטודנטים רוכשים בקורסים הקודמים ובתואר כולו לכדי הבנת תחום הלמידה בהקשר הארגוני, ניתוח תהליכי למידה וידע במחלקות שונות בארגון, הכרת מגוון פתרונות הדרכתיים והתאמתם ליעדים העסקיים של הארגון, מימוש של פתרונות ותוצרי למידה וחיבור לעולם העסקי. הפעילות בקורס מדמה ככל שניתן את המציאות העסקית – המתודולוגית – הטכנולוגית.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13141', 'טכנולוגיות למידה', 'קבלת החלטות מבוססת נתוני למידה', 3, 'סמסטר א׳', 2, 'בשנים האחרונות הולך ומתפתח בעולם תחום אנליטיקות הלמידה (Learning Analytics) שמתייחס לאיסוף, ניתוח ושימוש בנתונים אודות תהליכי למידה. חוקרים ואנשי למידה והדרכה רואים בתחום ככזה שיכול לתרום להבנה ושיפור תהליכים שנחוצים בארגונים שונים לרבות אלו העוסקים בחינוך, ממשל ותעשיה. כיום ברור כי יש צורך בהנגשת נתונים לבעלי העניין הארגונים באופן מותאם שיאפשר להם פענוח וקבלת החלטות באופן ידידותי. במהלך הקורס נכיר את המסגרת התיאורטית של תחום קבלת ההחלטות מנקודת מבט ארגונית, כמו גם את המסגרת המושגית של תחום קבלת החלטות מבוססת נתונים. הסטודנטים יחשפו למחקרים עדכניים בתחום ויתנסו בפרויקט קבוצתי שיכלול איסוף, ניתוח נתונים והצגת המלצות יישומיות לבעלי עניין.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13217', 'טכנולוגיות למידה', 'תכנות 3', 3, 'סמסטר א׳', 3, 'הכרה והבנת עקרונות של עבודה עם ספריות מבוססות JS ושילוב API''s מסביבות קיימות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13406', 'טכנולוגיות למידה', 'פרויקט גמר (שנתי)', 3, 'סמסטר א׳', 3, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13416', 'טכנולוגיות למידה', 'סמינר הדרכה וטכנולוגיות למידה בארגונים', 3, 'סמסטר ב׳', 1, 'לאפשר מפגש בלתי אמצעי בין סטודנטים לקראת סיום המסלול לבין שוק ההדרכה בישראל. להקנות כלים לתהליך הכניסה לשוק: איתור הזדמנויות, תהליכי מיון, פיתוח מקצועי לאורך זמן. לאפשר לסטודנטים ראיה קצרת וארוכת טווח באשר למסלול הפיתוח המקצועי שלהם בתחום.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('06530', 'טכנולוגיות למידה', 'חווית משתמש במעקב עיניים קורס אינטרדיסציפלינרי למדמ"ח וטל"מ', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13126', 'טכנולוגיות למידה', 'כריית מידע וניתוח למידה', NULL, NULL, NULL, 'מטרתו של הקורס היא להכיר לסטודנטים את תחום ניתוח הלמידה (learning analytics) ותרומתו למחקר ולשיפור תהליכי הוראה ולמידה. הקורס יחשוף את הסטודנטים לכלים ושיטות לניתוח תהליכי למידה, תוך שימוש בנתונים דיגיטליים הנאספים מסביבות למידה ממוחשבות. הסטודנטים ילמדו על מחקרים עדכניים בתחום ויתנסו בביצוע מחקר באמצעות תוכנות לעיבוד נתוני עתק וניתוחם.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13140', 'טכנולוגיות למידה', 'איך לקיים שיח עם מכונה מועצמת AI? Prompts וחשיבה ביקורתית', NULL, NULL, NULL, 'פריצת הדרך של בינה-מלאכותית יצרנית (Generative AI), טומנת בחובה הזדמנויות להעצמת האפקטיביות, היצירתיות והתודעה במגוון רוטינות היומיום לרבות אלו הקשורות לעבודה, לימודים ופנאי. מימושים המתכללים חידושים בתחום ה-AI, מזמנים אתגרים דרמטיים אף ביחס לאלו אותם חוותה האנושות בעבר במהלך אימוץ טכנולוגיות חדשות. אחד החידושים הבולטים בתחום זה נוגע לפקודות Prompt המאפשרות שיח אינטראקטיבי שכולל ניסוח שאילתות ובקשות ממכונה שמועצת ביכולות AI. היכולת לקבל תוצאות מושכלות מממשקי ה AI השונים דורשת דיוק ההנחיות המוצגת למכונה. בנוסף, הבנת מנגנון ה -Prompts מאפשר הזדמנויות לפיתוח חשיבה ביקורתית המשלבת הפעלת התנהגות אתית. קורס זה מיועד לסטודנטים לטכנולוגיות למידה ויקנה ידע תיאורטי ומעשי בהקשרים של הפעלה מיטבית של ממשק AI Prompt ככלי מקצועי בתחום עיצוב ופיתוח הלמידה. במהלך הקורס, הסטודנטים יתנסו בChatGPT וכלים נוספים המאפשרים שיח באמצעות Prompt AI. הסטודנטים ינצלו את הכלי בכדי ללמוד על תחום ה-AI כשלעצמו ועל דרכי השימוש בכלי לצורך השגת תוצאות מקצועיות מיטביות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13147', 'טכנולוגיות למידה', 'Responsible AI- Examination & Implementation of AI in Learning and Training', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13148', 'טכנולוגיות למידה', 'מתוצר למוצר – תהליכי פיתוח ובדיקות להפצת תוצרי למידה טכנולוגיים', NULL, NULL, NULL, 'הקורס מיועד לגשר בין פיתוח אקדמי של תוצרי למידה לבין הפצתם כמוצרים טכנולוגיים שלמים, נגישים ומוכנים לשימוש בשוק. הסטודנטים יתנסו בשדרוג פרויקטים קיימים ויקבלו כלים מתודולוגיים ופרקטיים לתהליכי פיתוח מקצה לקצה, כולל מחקרי משתמשים, בדיקות, שיפור ביצועים ואבטחת מידע.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13220', 'טכנולוגיות למידה', 'סייבר פסיכולוגיה – פסיכולוגיה במרחב הדיגיטלי', NULL, NULL, NULL, 'העידן הטכנולוגי והופעתם של האינטרנט, טכנולוגיות שונות, רשתות חברתיות ועוד הוביל לכך שהאופן בו אנו חושבים, מתייחסים, מֶתָקשרים ומׅתְקשרים, לומדים ועובדים השתנה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13226', 'טכנולוגיות למידה', 'מעבדה – חווית משתמש במעקב עיניים', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13242', 'טכנולוגיות למידה', 'מבוא לחווית משתמש במעקב עיניים', NULL, NULL, NULL, 'המונח חוויית משתמש (UX) התפתח רבות בעשור האחרון ומהווה נדבך מרכזי בתהליכי האפיון, העיצוב והפיתוח של תוצרים דיגיטליים. אחת הדרכים החדשניות להערכת חוויית משתמש מתבצעת באמצעות כלים למעקב תנועת עיניים (eye tracking). כלים אלה מאפשרים מדידה של היבטים התנהגותיים החיוניים בקבלת החלטות בתחום ה- UX לדוגמה, היכן הסתכל המשתמש לראשונה בממשק? מה משך את תשומת ליבו? ועוד. בקורס נלמד על השימושים המרכזיים בכלי למעקב עיניים, ניחשף למתודולוגיות מחקר המשלבות את הכלי במדעי ההתנהגות ונכיר את הכלי עצמו ואת המדדים המרכזיים הנאספים באמצעותו.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13511', 'טכנולוגיות למידה', 'פרויקטים מיוחדים', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13513', 'טכנולוגיות למידה', 'היבטים עסקיים בהדרכה', NULL, NULL, NULL, 'מטרת הקורס היא להקנות הבנה עסקית ולהכיר כלים בסיסיים בקבלת החלטות בעולם ההדרכה הארגונית ולהקנות כלים לקבלת החלטות עסקיות, לניהול עבודה מול ספקי משנה ואיך לשווק את ההדרכה (הן פנימית והן חיצונית).', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13515', 'טכנולוגיות למידה', 'עיצוב ממשק למכשירים ניידים', NULL, NULL, NULL, 'רוב הכניסות לרשת האינטרנט מבוצעות כיום באמצעות מכשירים אישיים ניידים (סמארטפונים למיניהם). שינוי זה מלווה בהתאמת ממשקי המשתמש של סביבות הרשת, ובכללן סביבות המיודעות להדרכה ולמידה, למאפיינים הייחודיים של המכשירים הניידים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13516', 'טכנולוגיות למידה', 'יזמות עסקית ב- Edtech', NULL, NULL, NULL, 'עידוד הסקרנות והמוטיבציה ליזמות עסקית באדטק, והרחבת האופקים לגבי ההזדמנויות ואפיקי היזמות האפשריים בתחום זה חשיפה לצד העסקי של תחום האדטק בארץ ובעולם הכרות ראשונית עם סוגי יזמות עסקית בתחום חשיפה למגמות בעולם', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13517', 'טכנולוגיות למידה', 'תוכנות גרפיות מתקדמות', NULL, NULL, NULL, 'הקורס עוסק בתוכנות המתבססות על גרפיקה וקטורית המאפשרת יצירה של התוצאה האיכותית ביותר האפשרית לתצוגת מסך ולפלט מודפס. נתמקד במיוחד בתוכנת האילוסטרייטור באמצעותה ניתן לעצב, ליצור ולאייר לוגואים, סמלים, פונטים, פריסות, שרטוטים, קעקועים, תכשיטים, שלטים, איורים, כרזות, מודעות, באנרים ואתרים (ללא הנפשה), הדמיות ועוד. בקורס נלמד להשתמש בתוכנת האילוסטרייטור ליצירת גרפיקה פשוטה ומורכבת בטכניקות עבודה נכונות ומקצועיות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13521', 'טכנולוגיות למידה', 'פיתוח קורסים מקוונים בפלטפורמת open edX', NULL, NULL, NULL, 'היכרות עם פלטפורמת EDX ועם קורסים מקוונים מרובי משתתפים (MOOCS) התנסות בבנייה קורס בפלטפורמת EDX תוך שימוש בכלי של edX ליצירת קורסים – Studio', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13526', 'טכנולוגיות למידה', 'חקר, יישום והתנסות בטכנולוגיות להעצמת תהליכי למידה בעידן הבינה המלאכותית', NULL, NULL, NULL, 'הקורס מציע היכרות יישומית עם מגוון אמצעים חדשניים לרבות כלים, סביבות, שפות תכנות, וספריות קוד שניתן לשלב בתהליכי פיתוח ואינטגרציה של טכנולוגיות לשרות העצמת תהליכי למידה והדרכה ארגונית (TEL). במהלך הקורס, המשתתפים.ות יתנסו בחקר, מימוש ותהליך למידת עמיתים שממוקד במגוון טכנולוגיות TEL. ההתנסות תעשה כחלק מתהליך חקר והתנסות מעשית דרך שיתוף פעולה בקבוצות, תוך התמקדות ביישום פתרונות טכנולוגיים חדשניים', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13550', 'טכנולוגיות למידה', 'תכנות מתקדם', NULL, NULL, NULL, 'הכרה והתנסות בגישות חדשות בפיתוח WEB ושילובם בסביבות למידה והדרכה טכנולוגיות. התנסות בחקר והדרכה במגוון טכנולוגיות קצה וגישות בפיתוח יישומים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13558', 'טכנולוגיות למידה', 'Technology for Users with Special Needs', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13562', 'טכנולוגיות למידה', 'ניהול משא ומתן', NULL, NULL, NULL, 'הקורס נועד להקנות יסודות תיאורטיים ומעשיים לניהול משא ומתן, תוך דגש על ניהול משא ומתן בתוך ארגונים. נבחן היבטים שונים של ניהול משא ומתן, כגון: השפעת התרבות על משאים ומתנים ארגוניים (לרבות תרבות ארגונית), כשלים במשא ומתן, אבחנה בין אינטרסים ליעדים במשא ומתן, השפעתן של אמוציות, מעורבות צד שלישי ועוד. כל זאת תוך התייחסות לתיאוריות שונות וממצאי מחקר מן השנים האחרונות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13818', 'טכנולוגיות למידה', 'שילוב טכנולוגיות ליישומים ניידים MMI', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13902', 'טכנולוגיות למידה', 'Including Human values in the design cycle of interactive digital tools', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13903', 'טכנולוגיות למידה', 'Media and manipulation in an age of synthetic reality: Implications for learning & development (L&D) and critical media-literacy', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13904', 'טכנולוגיות למידה', 'UX writing', NULL, NULL, NULL, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('13999', 'טכנולוגיות למידה', 'עיצוב גרפי מתקדם', NULL, NULL, NULL, 'קורס זה נועד להקנות לסטודנטים בטכנולוגיות למידה עקרונות עיצוב שונים תוך התייחסות ייחודית לעיצוב במדיה ובפורמט בה יבוצע פרויקט הגמר ולהקנות מיומנות גבוהה בתוכנות הגרפיות בהם משתמשים בתעשייה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-telem/'),
  ('41001', 'טכנולוגיות רפואיות דיגיטליות', 'חדו"א לרפואה דיגיטלית', 1, 'סמסטר א׳', NULL, 'פיתוח יכולת חשיבה מתמטית, והקניה של שיטות וכלים מתמטיים בסיסיים הנדרשים לסטודנט בקורסים מתקדמים בתכנית, כגון: מבוא להסתברות, מבוא לסטטיסטיקה, למידת מכונה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41003', 'טכנולוגיות רפואיות דיגיטליות', 'כימיה כללית ואנליטית', 1, 'סמסטר א׳', NULL, 'הקורס יקנה כלים וידע בסיסי להבנת עולם הכימיה, החל ממבנה האטום, דרך אינטראקציות בין-מולקולריות ועד לתכונות מאקרוסקופיות של חומר. בנוסף, הסטודנטים ילמדו עקרונות בכימיה אנליטית. כלים וידע אלו יהוו בסיס כימי רחב ומעמיק ללימודי מקצועות מדעי הרפואה. בקורס זה ינתן דגש על שימוש בכלים חישוביים ודיגיטאליים להדמיות ולסימולציות של ריאקציות כימיות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41004', 'טכנולוגיות רפואיות דיגיטליות', 'מתמטיקה בדידה לרפואה דיגיטלית', 1, 'סמסטר א׳', NULL, 'פיתוח יכולת חשיבה מתמטית-לוגית, באמצעות הכרות עם יסודות הלוגיקה המתמטית, תורת הקבוצות, יחסים וקומבינטוריקה; קורס זה הוא אחד מהקורסים העיקריים להבנת יסודות החישוב. בתום הקורס, התלמידים צפויים להכיר מושגי יסוד בלוגיקה, תורת הקבוצות, יחסים וקומבינטוריקה; לקבוע האם יחס נתון הוא יחס שקילות, יחס סדר או פונקציה; לדעת להשתמש בעקרונות יסודיים לספירה, כגון: עקרונות החיבור והכפל, עקרון ההכלה וההדחה ועקרון שובך היונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41005', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא למחקר מדעי – איסוף וניתוח נתונים', 1, 'סמסטר א׳', NULL, 'הכרות ראשונית של הסטודנט עם יסודות החשיבה המדעית ושפת המדע, לרבות אופני הביטוי המדעי המקובלים (כתיבה מדעית); הקורס יקנה לסטודנט: יכולת להבין את הקשר בין כתיבה מדעית לבין הבסיס הלוגי שבחשיבה מדעית; הבנה של כללי הכתיבה המדעית: תכנים, רצף לוגי, אזכורים ביבליוגרפיים, כללי ניסוח והדפסה; כישורי קריאה ביקורתית של פרסומים מדעיים, תוך התייחסות לכושר השכנוע של הטיעונים המוצגים בכל חלק ולאיכות הצגתם; התוודעות לתהליך הפרסום של חומר מדעי; יכולות בסיסיות בכתיבת טקסט מדעי.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41006', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא לתכנות בשפת Python', 1, 'סמסטר א׳', NULL, 'להקנות הבנה רחבה במושגי יסוד במדעי המחשב והתכנות; הקורס נועד ללמד את הסטודנט לחשוב בצורה אלגוריתמית, לפתור בעיות (חישוביות) באופן יעיל ולפתח ולעצב תכניות מחשב.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41008', 'טכנולוגיות רפואיות דיגיטליות', 'ביולוגיה של התא 1', 1, 'סמסטר א׳', NULL, 'הקניית בסיס להבנת מבנה ותפקוד התא, לרבות מנגנונים מולקולריים ותהליכים בסיסיים החיוניים לתפקודו התקין.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41032', 'טכנולוגיות רפואיות דיגיטליות', 'סדנת הכנה למחקר ופיתוח בסביבה קלינית', 1, 'סמסטר א׳', NULL, 'הקורס נועד להכיר לסטודנט מקרוב את האתגרים, הפתרונות והטכנולוגיות הקיימים בסביבה קלינית (בבית חולים או בקהילה), לצד סקירה קצרה אודות מערכת הבריאות בישראל.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41011', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא לסטטיסטיקה והסתברות 1 (לשעבר מבוא להסתברות לרפואה דיגיטלית)', 1, 'סמסטר ב׳', 4, 'פיתוח יכולת חשיבה אנליטית והקניה של שיטות וכלים מתמטיים בסיסיים מתורת ההסתברות, הנדרשים לסטודנט בקורסים מתקדמים בתכנית, כגון: מבוא לסטטיסטיקה לרפואה דיגיטלית, אפידמיולוגיה וחקר נתונים ביו-רפואיים, למידת מכונה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41012', 'טכנולוגיות רפואיות דיגיטליות', 'כימיה פיסיקלית', 1, 'סמסטר ב׳', 3.5, 'הקורס יקנה ידע בסיסי וכלים להבנת מנגנוני ריאקציה כימית מתוך בחינה כמותית של קצבי ריאקציה ובחינת התלות של קצב הריאקציה בטמפרטורה. הסטודנטים ילמדו לנתח ריאקציות כימיות, בדגש על ריאקציות אנזימטיות, בהיבטים של קבועי מהירות וקבועי שווי משקל. בנוסף, הסטודנטים יכירו את חוקי התרמודינמיקה, בדגש על מושגי יסוד, כגון: אנטרופיה, אנרגיה חופשית ופוטנציאל כימי ויבינו את הקשר בין האנרגיה החופשית הסטנדרטית של תהליך לבין קבוע שווי המשקל בריאקציות כימיות ובמעבר בין מצבי צבירה שונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41014', 'טכנולוגיות רפואיות דיגיטליות', 'אלגברה לרפואה דיגיטלית', 1, 'סמסטר ב׳', 4, 'הכרת מושגים והקניה של שיטות וטכניקות יסודיות באלגברה לינארית, הנדרשים לסטודנט בקורסים מתקדמים בתכנית בתחום מדעי הנתונים, כגון: למידת מכונה, שימושי למידה עמוקה בדימות רפואי, סמינריונים באינפורמטיקה רפואית ושיטות חיזוי ומבוא לעיבוד אותות פיסיולוגיים (בחירה).', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41015', 'טכנולוגיות רפואיות דיגיטליות', 'מבני נתונים ואלגוריתמים', 1, 'סמסטר ב׳', 4, 'להקנות הכרה והבנה של מבני נתונים ואלגוריתמים בסיסיים במדעי המחשב; ליישם מבני נתונים ואלגוריתמים יסודיים במדעי המחשב בשפת התכנות Python.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41016', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא לגנטיקה', 1, 'סמסטר ב׳', 3, 'להקנות לסטודנט ידע בסיסי בגנטיקה בכלל ובגנטיקה של האדם בפרט: החל מהכרת החומר הגנטי – מבנהו ותפקודו בתא – דרך הכרת מנגנוני הבקרה והתיקון של ה- DNA ושל הגנים השונים, הבנת התהליכים התאיים המשמשים לבקרת גנים, ועד היחס בין הגנוטיפ לפנוטיפ; בהקשר זה, יושם דגש על האדם ובפרט על שינויים וחידושים במחקר הביולוגי וברפואה בשנים האחרונות מאז פענוח הגנום האנושי, עליו הוכרז בראשית מילניום זה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41017', 'טכנולוגיות רפואיות דיגיטליות', 'כימיה אורגנית 1', 1, 'סמסטר ב׳', 3, 'בקורס זה יכירו הסטודנטים את התרכובות הפחמימניות (hydrocarbons), ובכלל זה גם את ההבדלים בין אלקאנים, אלקנים ואלקינים, ותילמד הנומנקלטורה הייחודית של התרכובות האורגניות. הקורס יסקור את הריאקציות הכימיות העיקריות בהן משתתפות התרכובות הללו, לרבות מנגנוני הריאקציות והפרופילים האנרגטיים שלהן. כמו כן, הסטודנטים יכירו את התרכובות הארומטיות וילמדו מהי איזומריזציה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42020', 'טכנולוגיות רפואיות דיגיטליות', 'מעבדת תכנות מתקדם בשפת Python', 1, 'סמסטר ב׳', 1.5, 'להקנות ידע יישומי בתכנות בשפת Python בדגש על צרכים של מדעי הנתונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41013', 'טכנולוגיות רפואיות דיגיטליות', 'ביוכימיה 1', 2, 'סמסטר א׳', 3.5, 'הכרת מושגי יסוד בביוכימיה; הכרת שפת הביוכימיה, בכל הקשור למבנה, תפקיד ומטבוליזם של חומרים בגוף האדם ברמה התאית והמולקולרית; הבנת הזיקה בין ביוכימיה לבין תחומים אחרים במדעי הרפואה והתזונה, בפרט בכל הנוגע לקשר בין המבנה המורכב של מולקולות ורב-מולקולות אורגניות לבין פעילותן הביולוגית; הבנת המנגנונים הביוכימיים הגורמים להפרעות פתולוגיות נרכשות ותורשתיות; הבנת המסלולים המטבוליים היסודיים, לרבות מנגנוני פעולה וויסות של אנזימים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41018', 'טכנולוגיות רפואיות דיגיטליות', 'כימיה אורגנית 2', 2, 'סמסטר א׳', 3, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41019', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא למדעי הנתונים לרפואה דיגיטלית', 2, 'סמסטר א׳', 4, 'להקנות רקע בסיסי במדעי הנתונים, תחום ההולך ומתפתח; הקורס נלמד במקביל לקורס (התיאורטי) מבוא לסטטיסטיקה לרפואה דיגיטלית, מתוך כוונה להכניס את הסטודנט לעולם מדעי הנתונים (תיאוריה – מושגים, דוגמאות ויישומים), בד בבד עם תרגול ההיבטים התיאורטיים הנלמדים בקורס: מבוא לסטטיסטיקה לרפואה דיגיטלית, באמצעות הרכשת יסודות שפת R; להכיר את יסודות שפת R ושימושיה במדעי הנתונים (בדגש על נתונים רפואיים).', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41020', 'טכנולוגיות רפואיות דיגיטליות', 'כימיה אורגנית 2', 2, 'סמסטר א׳', 3, 'להכיר את חשיבות הבינה המלאכותית ולהבין את יכולותיה ומגבלותיה בהתמודדות עם בעיות קלאסיות כמו גם עם בעיות עכשוויות, להקנות הכרה והבנה של הטכניקות העיקריות של בינה מלאכותית (גישות, שיטות ואלגוריתמים) לפתרון מגוון בעיות, ליישם את הטכניקות הנ"ל בשפת התכנות Python.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41021', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא לסטטיסטיקה והסתברות 2 (לשעבר: מבוא לסטטיסטיקה לרפואה דיגיטלית)', 2, 'סמסטר א׳', 3, 'לספק כלים תיאורטיים ומעשיים לניתוח נתונים והסקה סטטיסטית; הקורס נועד להקנות מושגים בסיסיים בסטטיסטיקה, יכולת לחשוף ולחקור תכונות של אוכלוסיה (התפלגות) מתוך מדגם הנלקח ממנה, ולהשוות אוכלוסיות (התפלגויות) שונות מתוך מדגמים שנלקחו משתיהן, בלתי תלויים ותלויים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41022', 'טכנולוגיות רפואיות דיגיטליות', 'בסיסי נתונים ביו-רפואיים', 2, 'סמסטר א׳', 4, 'להעניק לסטודנט הבנה של יסודות מסדי הנתונים, להקנות יכולת תכנון סכמות של מסדי נתונים וניסוח שאילתות, להכיר צורות חדשות של אחסון ושליפה של נתונים, להבין את הייחודיות והמורכבות של בסיסי נתונים ביו-רפואיים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41024', 'טכנולוגיות רפואיות דיגיטליות', 'ביוכימיה 2 (לשעבר: תהליכים תאיים)', 2, 'סמסטר ב׳', 3, 'הקניית ידע במנגנונים המולקולריים והתהליכים הביוכימיים החיוניים לתפקודו התקין של התא ושל הגוף כולו. יינתן דגש מיוחד על: הקשר בין מבנה לתפקוד; ויסות מסלולים מטבוליים, לרבות תהליכים פתולוגיים הקשורים בהם; קשרים בין מטבוליזם לתזונה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41025', 'טכנולוגיות רפואיות דיגיטליות', 'ביולוגיה מולקולרית', 2, 'סמסטר ב׳', 4, 'להקנות לסטודנטים את יסודות הביולוגיה המולקולרית, לצד הבנה של התהליכים, המנגנונים ושיטות המחקר המקובלות כיום בתחום, בפרט בהקשר לשיטות אבחון; הקורס יקנה לסטודנט הבנה של מכלול הגורמים המשפיעים על הביטוי הסופי של הגן (הפנוטיפ), לרבות סביבה והתנהגות. במסגרת הקורס תיסקרנה גישות מחקר אינטגרטיביות, המשלבות את עולמות האפידמיולוגיה ומדעי הנתונים (למשל, נתוני עתק – Big Data), לפיתוח פתרונות רפואה מותאמת אישית (Personalized Medicine).', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41026', 'טכנולוגיות רפואיות דיגיטליות', 'מחסני נתונים ובינה עסקית-קלינית', 2, 'סמסטר ב׳', 4, 'להקנות לסטודנט ידע בסיסי באופן פעולתן של מערכות בינה עסקית בכלל ומערכות בינה עסקית-קלינית בפרט; להכיר מודלים ניהוליים והנדסיים של בינה עסקית (בפרט בארגונים רפואיים); ללמד את המתודולוגיה לתכנון והקמה של מחסני נתונים; לממש תהליכים עסקיים במרחב הרפואי במחסני נתונים; להכיר את תהליכי האיסוף, השילוב והטיוב של נתונים רפואיים; להבין את חשיבות היבט האיכות, והתהליכים הקשורים לכך, בכל הקשור לנתונים בכלל ונתונים רפואיים בפרט; להבין כיצד מנתחים נתונים (רפואיים) רב-ממדיים;', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41027', 'טכנולוגיות רפואיות דיגיטליות', 'אפידמיולוגיה וחקר נתונים ביו-רפואיים', 2, 'סמסטר ב׳', 3.5, 'הקניית מושגים בסיסיים ומתקדמים באפידמיולוגיה, לצד הכרה והתנסות בשיטות וכלים חישוביים לחקר נתונים ביו-רפואיים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41028', 'טכנולוגיות רפואיות דיגיטליות', 'למידת מכונה', 2, 'סמסטר ב׳', 4, 'הכרת מושגי יסוד בלמידת מכונה (Machine Learning); הקניית רקע תיאורטי ומעשי של השיטות המתקדמות ביותר בתחום למידת מכונה; יישום ותרגול של תהליך העבודה עם המודלים, תוך כדי לימוד כיצד לבחור נכונה את האלגוריתם המתאים למטרות המשימה הרצויה; הבנת האופנים באמצעותם ניתן לשפר את הביצועים של המודל הנבחר; יישום הנלמד באמצעות שפת Python, תוך התבססות על ספריית scikit-learn.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41033', 'טכנולוגיות רפואיות דיגיטליות', 'סדנת הכנה לפרויקט הגמר', 2, 'סמסטר ב׳', 2, 'הקורס נועד להכיר לסטודנט את מאפייני ותכולת פרויקט הגמר הנעשה בשנה השלישית, ואשר יתבסס על צורך ממשי/אמיתי בסביבה קלינית.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41118', 'טכנולוגיות רפואיות דיגיטליות', 'תכנות מתקדם למחקר ביו-רפואי', 2, 'סמסטר ב׳', 4, 'להעמיק את ההבנה של הסטודנט בתכנות בכלל ובשפת Python בפרט,לתכנן ולממש מערכות תוכנה מורכבות ב-Python תוך שימוש בעקרונות OOP מתקדמים, להפוך קוד אנליטי שנכתב בסביבת Notebook לאפליקציה מודולרית, אמינה וברת-בדיקה, להכיר לעומק היבטים מתקדמים של תכנות כגון: רקורסיה, תכנות רשת ומתודולוגיית Event-Driven, לתכנן וליישם ארכיטקטורות מבוזרות וא-סינכרוניות באמצעות תורי הודעות, לנצל את משאבי המערכת ביעילות ע"י מימוש לוגיקה מקבילית, לארוז ולפרוס אפליקציות מלאות לסביבת ענן (AWS).', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41111', 'טכנולוגיות רפואיות דיגיטליות', 'פרויקט מו"פ', 3, 'סמסטר א׳', 4, 'לסייע לסטודנטים להכיר את תהליך העבודה – שלבי התכנון, הביצוע וניהול הפרויקט, בהתאם לדרישות שיפורסמו מעת לעת ע"י צוות הקורס; הפרויקט עצמו נועד לאפשר לסטודנטים להוציא מן הכח אל הפועל וליישם את כל הידע המולטי-דיסציפלינרי שצברו בכל אשכולות הלימוד בתכנית – מבואות/מדעים, מדעי הרפואה וטכנולוגיות מידע – לצורך גיבוש מענה טכנולוגי לאתגר קיים בתחום הרפואה הדיגיטלית.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42001', 'טכנולוגיות רפואיות דיגיטליות', 'אחזור וכריית מידע', 3, 'סמסטר א׳', 3.5, 'הכרת מושגי יסוד ותהליכים בסיסיים של מערכות אחזור מידע וטכניקות לכריית נתונים; לימוד האלגוריתמים הבסיסיים והטכניקות הנפוצות לאחזור מידע (מפתוח ושליפה של מסמכים, עיבוד שאילתה ועוד); הכרת שיטות הערכה כמותיות למערכות אחזור מידע וטכניקות כריית נתונים; הבנת הטכניקות והאלגוריתמים שבבסיס יישומים של מערכות אחזור וכריית נתונים כדוגמת מנועי חיפוש ברשת, מערכות המלצה ועוד.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42002', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא למיקרוביולוגיה רפואית', 3, 'סמסטר א׳', 4, 'הכרות עם מושגי יסוד במיקרוביולוגיה רפואית בהקשר של מיקרואורגניזמים מחוללי מחלות, המחלות אותן הם גורמים ותגובת גוף האדם כנגדם; הבנת הזיקה בין תהליכים מיקרוביאליים לבין תנאי/איכות הסביבה בה אנו חיים, לרבות יחסי גומלין בין המיקרואורגניזמים לבין עצמם וביניהם לסביבה, מניעת זיהומים/מחלות והתמודדות עמם.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42005', 'טכנולוגיות רפואיות דיגיטליות', 'היבטים פסיכולוגיים של מצבי חולי ונכות', 3, 'סמסטר א׳', 2, 'מטרת הקורס היא להקנות תפיסה אינטגרטיבית של הקשר בין השלכות רפואיות של נכויות פיזיות ומחלות אקוטיות וכרוניות לבין התמודדות הפרט במצבים אלו ברמה הפסיכולוגית והסוציאלית.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42006', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא למדעי המוח והקוגניציה', 3, 'סמסטר א׳', 2, 'הכרת מערכת העצבים המרכזית באדם, בפרט המוח, בהיבטי מבנה, תפקוד ועקרונות פעולה; הכרות עם תיאוריות, שיטות מחקר ועדויות אמפיריות במדעי הקוגניציה (פסיכולוגיה קוגניטיבית, בעיקר) אודות מבנים ותהליכים מנטליים, שהם ביסוד התפקוד הקוגניטיבי בהקשר לזיכרון (לסוגיו), קשב וריכוז, קבלת החלטות וחשיבה רציונלית; יצירת זיקה בין מבנה ותפקוד המוח לבין תהליכים בסיסיים של חישוב ועיבוד מידע במוח האדם; הכרת פתולוגיות נפוצות בתחום הנוירולוגיה, אתגרים ודרכי טיפול; תיאור אירועים גופניים והתנהגותיים בחיי היומיום תוך שימוש במונחים תיאורטיים הנלמדים בקורס.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42027', 'טכנולוגיות רפואיות דיגיטליות', 'פיזיולוגיה תאית ונוירופיזיולוגיה', 3, 'סמסטר א׳', 4, 'הקורס נועד להקנות את יסודות הפיזיולוגיה ברמת התא והרקמה בד בבד עם עקרונות יסוד בנוירופיזיולוגיה. בתום הקורס, הסטודנט צפוי: להכיר את מבנה התא ואת תהליכי מעבר חומרים דרך ממברנת התא; להבין את התכונות החשמליות של תאי עצב כבסיס לתקשורת ביניהם לבין עצמם וביניהם לתאים אחרים בגוף; להכיר את סוגי הסינפסות הקיימות ואת הנוירוטרנסמיטורים העיקריים; להבין את המיקרו-אנטומיה של סיבי שריר שלד, התכונות החשמליות והמכניות של תאי שריר שלד ושריר חלק.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43002', 'טכנולוגיות רפואיות דיגיטליות', 'ויזואליזציה של מידע ביו רפואי', 3, 'סמסטר א׳', 2, 'הקורס נועד להקנות כלים ומיומנויות באנליזה של נתונים ביו-רפואיים, תוך התמקדות בהיבטים שונים של ויזואליזציה של מידע מעובד/לא מעובד ותוצאים. בנוסף, הקורס יקנה לסטודנט ידע והבנה אודות השימוש באנליזה של נתונים ביו-רפואיים והצגה ויזואלית של מידע מעובד ותוצאים לצורך קבלת החלטות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43003', 'טכנולוגיות רפואיות דיגיטליות', 'סמינריון באינפורמטיקה ביו-רפואית', 3, 'סמסטר א׳', 2, 'הכרת מושגי יסוד באינפורמטיקה רפואית; הקניית ידע בנושאים הנלמדים, במתן דגש על חשיבות הקידוד הרפואי עבור מערכות מידע רפואי; הכרה והבנה של הארכיטקטורה היסודית (הגנרית) של מערכת מידע רפואי, תוך התנסות בעבודה עם מערכות מובילות; הבנת אופני השימוש במאגרי מידע רפואי לצורך קבלת החלטות אינדיבידואליות ומערכתיות; הדגשה והפנמה של החשיבות באבטחת המידע הרפואי.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43004', 'טכנולוגיות רפואיות דיגיטליות', 'Big bio-medical data', 3, 'סמסטר א׳', 2, 'להקנות לסטודנטים ידע בסיסי בתחום נתוני עתק, בדגש על נתוני עתק ביו-רפואיים (לרבות יישומים במערכות מידע רפואיות); ללמוד את העקרונות העומדים מאחורי בסיסי נתונים מבוזרים; לרכוש ידע וכלים שיאפשרו לסטודנטים לקחת חלק בפרויקטים מבוססי נתוני עתק ברפואה, המשותפים למספר רב של משתמשים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42004', 'טכנולוגיות רפואיות דיגיטליות', 'שיח רופא-מטופל בעידן הדיגיטלי', 3, 'סמסטר ב׳', 2, 'להקנות הבנה אודות חשיבות מערכת היחסים בין המטפל (הרופא, בעיקר) למטופל, משמעותה לטיפול וכיצד טכנולוגיה יכולה לסייע או להזיק במצבים שונים; על ידי חשיפת הסטודנטים לעולם המטפלים והמטופלים, יאפשר הקורס הבנה של הצרכים והאופנים הנכונים לפיתוח, הטמעה ושימוש בטכנולוגיות מסייעות למטפלים ולמטופלים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42007', 'טכנולוגיות רפואיות דיגיטליות', 'אנטומיה ופיזיולוגיה של מערכות', 3, 'סמסטר ב׳', 3.5, 'להקנות ידע נרחב על מבנה ותפקוד מערכות פיזיולוגיות ייחודיות בגוף האדם וליצור תשתית להבנת פעולות מורכבות יותר של הגוף.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42008', 'טכנולוגיות רפואיות דיגיטליות', 'טיפול תרופתי בעידן הדיגיטלי', 3, 'סמסטר ב׳', 3, 'להקנות ידע בסיסי בעקרונות הפרמקולוגיה הקלינית (פרמקו-קינטיקה, פרמקו-דינמיקה, פיתוח תרופות חדשות וכדומה) והכרת מושגי יסוד; הכרת והבנת מצבים פתולוגיים במערכות הגוף השונות ומנגנוני פעילות של תרופות המותאמות למצבים אלה; רקע בהבנה של תגובות בין-תרופתיות ותופעות לוואי; ידע אודות אינטראקציה קיימת בין עולם הפרמקולוגיה לבין טכנולוגיות דיגיטליות, לרבות אתגרים ופתרונות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42009', 'טכנולוגיות רפואיות דיגיטליות', 'Challenges of the third and fourth age in the digital era', 3, 'סמסטר ב׳', 2, 'להציג את האתגרים וההזדמנויות של אנשים זקנים בעידן הדיגיטלי, בדגש על אופן החיבור בין המאפיינים והצרכים של דור הזקנים הנוכחי והדור הבא לבין היוזמות הטכנולוגיות, וחשיבות שילוב קהל היעד – הזקנים – בתהליכי הפיתוח; הכרת תקופת הזקנה "החדשה", ההזדמנויות והאתגרים הטמונים בה, לאדם, לחברה ולמערכות השירותים, כבסיס להבנת תפקיד ויכולת המענים הטכנולוגיים, כמו גם החסמים בעידן הדיגיטלי להשתלבותו של הזקן במערכות השירותים והחברה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42010', 'טכנולוגיות רפואיות דיגיטליות', 'מעבדה חיה (living lab) לפיתוח טכנולוגיות לגיל השלישי והרביעי', 3, 'סמסטר ב׳', 2, 'להקנות לסטודנט ידע על תהליך פתוח מוצר משלבי זיהוי הצרכים ועד ההטמעה בשוק, בפרט בהקשר לאתגרים ופתרונות הקשורים לאוכלוסיות הגיל השלישי והרביעי; להקנות כלים למחקר ופתוח של מוצרים הנוגעים בעולם הרפואי-החברתי, המשלבים משתמשי קצה; להיחשף לעבודה מחקרית-יישומית המלווה אפיון, פתוח והטמעה של מוצרים לגיל השלישי והרביעי; לסגל יכולות עבודה בצוות מולטי-דיסציפלינרי במחקר ופיתוח; להכיר את היסודות עליהן מושתת הקונספט של מעבדה חיה (Living Lab);', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42011', 'טכנולוגיות רפואיות דיגיטליות', 'ניתוח וקבלת החלטות בעולם הרפואי', 3, 'סמסטר ב׳', 2, 'מטרת הקורס היא להקנות לתלמידים הבנה בניסוח ובניתוח של בעיות החלטה בכלל והחלטה בתנאי אי-ודאות בעולם הרפואי בפרט.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43005', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא לעיבוד שפה טבעית', 3, 'סמסטר ב׳', 3, 'להכיר את המורכבות של המידול בשפות אנושיות; לרכוש ידע מעשי בפתרון משימות בתחום ניתוח טקסט ו- NLP – מסווג מסמכים ועד לתרגום מכונה; ללמוד וליישם את הטכניקות והאלגוריתמים הבסיסיים בתחום ה- NLP ; להבין גישות תחביר וסמנטיקה, גישות לשיח, יצירת דיאלוג וניהולו במכונה ושיטות קיימות לגישות סטטיסטיות לתרגום מכונה; להכיר וליישם טכניקות מלמידת מכונה בתחום ה- NLP.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43006', 'טכנולוגיות רפואיות דיגיטליות', 'שימושי למידה עמוקה בדימות רפואי', 3, 'סמסטר ב׳', 3, 'הכרת מושגי יסוד בראייה ממוחשבת (Computer Vision) ולמידה עמוקה (Deep Learning); הקניית רקע תאורטי ומעשי של השיטות המתקדמות ביותר בתחום למידה עמוקה ליישומי דימות רפואי; יישום ותרגול של תהליך העבודה עם המודלים, תוך כדי לימוד כיצד לבחור נכונה את האלגוריתם המתאים למטרות המשימה הרצויה; יישום הנלמד באמצעות שפת Python, תוך התבססות על ספריות OpenCV ו- TensorFlow; התמודדות עם בעיות ונתוני אמת בתחום הדימות הרפואי.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43007', 'טכנולוגיות רפואיות דיגיטליות', 'תקשורת נתונים ואבטחת מידע', 3, 'סמסטר ב׳', 4, 'הכרת מושגי יסוד בתחום רשתות תקשורת מחשבים; הבנת השיטות והאלגוריתמים הנפוצים בפעולת רשתות מחשבים; הבנת הארכיטקטורה של האינטרנט, הכרת פרוטוקולים נפוצים והאופן שבו הם פועלים; הכרת עקרונות ומושגי יסוד באבטחת רשתות והאינטרנט.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('43008', 'טכנולוגיות רפואיות דיגיטליות', 'מחשוב ענן', 3, 'סמסטר ב׳', 2.5, 'הכרת מושגים ועקרונות מחשוב ענן; הכרת ספקים, גישות ופלטפורמות מחשוב ענן; עיצוב, פיתוח ורתימת שירותים בענן לאחסון ולעיבוד נתוני עתק.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41034', 'טכנולוגיות רפואיות דיגיטליות', 'סוגיות בביו-אתיקה', NULL, NULL, 2, 'לעודד את הסטודנטים לפתח חשיבה ביקורתית ובחינה מעמיקה של ההיבטים החברתיים/תרבותיים של המדע והמחקר, בפרט הרפואי-טכנולוגי, בימינו.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41036', 'טכנולוגיות רפואיות דיגיטליות', 'קריאה ביקורתית ופענוח של מאמרים רפואיים', NULL, NULL, 2, 'לחשוף את הסטודנטים לתת מרכיבי קריאה ביקורתית של מאמרי מחקר רפואי- פרוש, שיפוט והצעות. בתום הקורס, הסטודנטים יוכלו לסקור באופן ביקורתי ספרות מחקר מדעי רפואי. וזאת, תוך: זיהוי חוזקות וחולשות המחקר שפורסם ,הבנת מערך המחקר והערכת התאמת שיטות הניתוח למחקר המסוים, הכרות עם סקירת ספרות איכותנית, מטא-אנליזה וניתוח משוקלל. ובנוסף, לימוד יכולות לתקשורת והצגת ממצאים לקהל מקצועי.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41037', 'טכנולוגיות רפואיות דיגיטליות', 'רפואה, נאציזם והשואה', NULL, NULL, 2, 'הקורס מבקש להקנות לסטודנטים: הכרת העובדות ההיסטוריות הרלוונטיות; הבנת הרצף מאאויגניקה לרצח עם, ואת תפקיד הרופאים והרפואה בו; הכרת הניסויים הרפואיים בעוולה, את קוד נירנברג והצהרת הלסינקי ותפקידם בביו-אתיקה עכשווית; הכרת הסיכון ברפואה וטכנולוגיה לשימוש לרעה בכוח; מתן דוגמאות של התנהגות רופאים ואחיות ראויה בתנאים בלתי אפשריים, והבנת משמעותם; הקורס יעסוק ברפלקציה על התכנים דלעיל ובמשמעותם עבורו ועבור זהותו המקצועית ו/או האישית של הסטודנט.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41038', 'טכנולוגיות רפואיות דיגיטליות', 'הרופא בעידן הדיגיטלי', NULL, NULL, 2, 'להקנות לסטודנטים הכרה והכנה למציאות הדיגיטלית המשתנה, לחשוף אותם ליישומים דיגיטליים בעלי רלוונטיות לתפקוד רופאים ולשדרוג מיומנויותיהם בתחום, להרחיב את ההכרות עם הספקטרום הרחב של יישומי טכנולוגיות המידע ברפואה ולאפיין את הכישורים להם יזדקקו רופאים, אנשי מקצועות הבריאות וטכנולוגים רפואיים מכל סוג שהוא כדי לתפקד במרחב מתפתח זה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41039', 'טכנולוגיות רפואיות דיגיטליות', 'סמינריון מחקר – רפואה חישובית', NULL, NULL, 2, 'לאפשר לסטודנטים התנסות פרקטית בקריאה, בניתוח והצגת מאמרים בתחום הרפואה החישובית; ללמד את הסטודנטים כיצד לזהות חוזקות וחולשות במאמר וכיצד יש להשוות בין מאמרים אחרים העוסקים באותו נושא; העמקת הידע בנושאים עדכניים בתחום הרפואה החישובית', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41042', 'טכנולוגיות רפואיות דיגיטליות', 'רובוטיקה פורצי דרך ברפואה ובבריאות', NULL, NULL, 3, 'הקורס מעניק לסטודנטים הבנה מעמיקה של עולם הרובוטיקה הרפואית, תוך התמקדות בשורשיה כתחום רב-תחומי המשלב הנדסה, מדע ורפואה. ידע נרחב בתחומי מכניקה, אלקטרוניקה, בינה מלאכותית, הנדסת אנוש, בטיחות, אנטומיה ופיסיולוגיה נותן בסיס איתן להבנת האתגרים וההזדמנויות בתחום. לשם כך מטרת הקורס לאפשר: הכרת עולם הרובוטיקה הרפואית ברמת סוגי הרובוטים הקיימים ושימושיהם במערכות בריאות, הבנת החשיבות של ממשק אדם-רובוט (HRI) והזיקה ל- AI, הבנת האופנים השונים של שיתוף מידע בין רובוטים רפואיים לבין מערכות מידע רפואיות, הכרת מתודולוגיות פיתוח והטמעה של רובוטים בעולמות הרפואה והבריאות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41113', 'טכנולוגיות רפואיות דיגיטליות', 'ביולוגיה של התא 2', NULL, NULL, 2, 'להקנות לסטודנטים ידע מתקדם בתפיסה הביולוגית של תפקוד התא הבודד ותפקוד מערכות תאים – הן במצבי בריאות והן במצבי חולי; הסטודנטים יכירו לעומק את מחלת הסרטן על כל היבטיה כפלטפורמה לימודית מרכזית לנושא זה. בנוסף, הסטודנטים יכירו ויעמיקו בהבנת תפקוד מערכת החיסון בבריאות ובחולי, כאמצעי להפנמת נושא תפקוד התא הבודד ותפקוד מערכות תאים משולבות בגוף האדם. הסטודנט ייחשפו לטכנולוגיות דיאגנוסטיקה וטכנולוגיות טיפוליות חדשניות בתחומי הסרטן, תרפיה תאית, רפואה מותאמת אישית וכיו"ב.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41114', 'טכנולוגיות רפואיות דיגיטליות', 'מחזור החיים של טכנולוגיה רפואית', NULL, NULL, 3, 'לספק בסיס ידע רחב לכלים להערכה וניתוח של שלבי ההתפתחות של טכנולוגיות רפואיות ושל הסביבה הרלוונטית, ככלי לתכנון נכון ויעיל וככלי תומך החלטה מהרעיון ועד לאימוצה ולהטמעתה בהצלחה בפרקטיקה הנוהגת; להכיר ולהבין מהו ניתוח מדעי ותכנון יעיל של שלבי הפיתוח של טכנולוגיה רפואית וכיצד מערבים בשלבים הנכונים את הגורמים הרלוונטיים. נושאים הקורס עוסק בהכרת מחזור חייה של טכנולוגיה רפואית ומחולק לשלושה חלקים: מבוא, שלב טרום-אישור (pre-approval) הטכנולוגיה לשווק ושלב בתר-אישור (post-approval) הטכנולוגיה לשווק. הקורס ילווה לכל אורכו בניתוח מקרים (אמיתיים). הנושאים שיילמדו: רגולציה בעולם הבריאות, ניסויים קליניים, הערכה של טכנולוגיות רפואיות, תהליכי אימוץ והטמעה ושוק הבריאות. הסטודנטים ילמדו שיטות ויקבלו כלים להערכה וניתוח של טכנולוגיה רפואית בשלבי התפתחותה השונים, תוך זיהוי והתייחסות לכלל ההיבטים הסביבתיים, הפנימיים והחיצוניים, המשפיעים על תהליכים אלו (משרד הבריאות, קופות חולים, חברות ביטוח, רשויות רגולטוריות, רופאים, מובילי דעה, צוות רפואי, מטופלים, איגודים מקצועיים ועוד), כולל ניתוח האינטראקציות ביניהם.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('41117', 'טכנולוגיות רפואיות דיגיטליות', 'שיטות חישוביות במדעי הנתונים', NULL, NULL, 3, 'להקנות לסטודנט שליטה בשיטות ובכלים חישוביים הנדרשים לבניה והבנה של אלגוריתמים ומודלים בעולם מדעי הנתונים, לרבות נתונים בצורת תמונות; לקנות לסטודנט הכרות ועבודה עם ספריות מתמטיות בשפת פייתון, הנפוצות בעיבוד וניתוח נתונים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42013', 'טכנולוגיות רפואיות דיגיטליות', 'רפואה מרחוק', NULL, NULL, 2, 'לחשוף את הסטודנטים להיבטים שונים של רפואה מרחוק כמרכיב משמעותי ברפואת העתיד, על מנת שיבינו את היתרונות, המגבלות והאתגרים הטמונים ברפואה מרחוק, תוך כדי הכרות עם המתודולוגיות והטכנולוגיות העיקריות המשמשות כיום ברפואה מרחוק.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42014', 'טכנולוגיות רפואיות דיגיטליות', 'סווג רקמות והשתלת איברים ברפואה ובמשפט', NULL, NULL, 2, 'לחשוף את הסטודנטים להיבטים השונים של עולמות סווג הרקמות והשתלות האיברים, להבין את חשיבות ההשקה והשילוב המולטי-דיסציפלינרי בין גנטיקה מחד ואימונולוגיה מאידך, להכיר את האתגרים המדעיים-טכנולוגיים, הקליניים והאתיים בתחום השתלות האיברים, לרבות השתלות מח עצם ותאי גזע, ולהתוודע ליישומים נוספים של סווג רקמות: רפואה משפטית, בדיקות קשרי משפחה, מקרים מיוחדים של ''זיהוי הומאני'' ברפואה ובמשפט.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42015', 'טכנולוגיות רפואיות דיגיטליות', 'חישה ואבחון רפואי בסביבה ביתית', NULL, NULL, 3, 'להכיר אמצעי חישה של מדדים פיסיולוגיים והתנהגותיים בסביבה הטבעית של המטופל, להבין אופני ותהליכי עיבוד של אמצעי חישה אלה ואת הנדרש לצורך מעבר ממערכות עם חיישן אחד למערכות המשלבות מספר חיישנים, להכיר מדדים סובייקטיביים להערכת מצב המטופל ולהיות מסוגלים להצליב מידע אובייקטיבי (חישה ועיבוד מלאכותי) עם מדדי הערכה (כדוגמת UPDRS, להערכת מצב חולה פרקינסון), כמו גם להיחשף לטכנולוגיות קיימות בתחום החישה והאבחון בסביבה הביתית במקביל לכיווני מחקר עתידיים.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42016', 'טכנולוגיות רפואיות דיגיטליות', 'פיתוח יישומים רפואיים', NULL, NULL, 3.5, 'הבנת הצרכים והיתרונות בקשר הטכנולוגי (והלא-טכנולוגי) של רופא/מטפל-מטופל; הכרת השאלונים הרפואיים, המעקבים התרופתיים ושאר אפשרויות התקשורת הדיגיטלית בין המטפל/הרופא למטופל; הכרות מעמיקה עם אנדרואיד (מערכת ההפעלה המובילה בעולם); לימוד שפת התכנות Kotlin (קוטלין), תוך שימת דגש על תכנות פונקציונלי מסדר גבוה ותכנות מונחה עצמים; הכרת כלל אבני הבניין – הוויזואליים והלוגיים – המשמשים לבניית אפליקציה; הקניית היכולת לעבוד עם מסדי נתונים מקומיים ומאובטחים לשמירת מידע רפואי אישי; הקניית יכולת עבודה עם מסדי נתונים מרוחקים לצורך יצירת מאגר נתונים משותף עם המטפל/הרופא; מתן היכולת לתקשורת מלאה עם רכיבי וחיישני המכשיר הנייד, תוך עיבוד ושמירת המידע המתקבל מהם לצורך הסקת מידע על מצב המטופל; מתן היכולת ליצירת תקשורת מלאה עם מערכת ההפעלה, בין היתר לצורך תזמון משימות ותזכורות עתידיות, כמו גם ליצירת שרותי רקע ללא ממשק, אשר מטרתם לבצע מעקב רפואי; הקניית יכולת מעשית/יישומית ליצור פרויקטים מורכבים (במתכונת יישומים במובייל) באופן עצמאי.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42017', 'טכנולוגיות רפואיות דיגיטליות', 'מבוא לפיסיקה רפואית ומערכות דימות', NULL, NULL, 2.5, 'הכרה והבנה של העקרונות הפיסיקליים של על-קוליות, קרינה אלקטרו-מגנטיות ותהודה מגנטית; הכרה והבנה של עקרונות הפעולה ותכונותיהן של מערכות דימות רפואיות שונות, והשיקולים הפיסקליים העומדים מאחוריהם; הכרת העקרונות המשפיעים על תכונות מערכות דימות רפואיות, ועל תכונות התמונה המתקבלת.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42021', 'טכנולוגיות רפואיות דיגיטליות', 'התנסות מעשית בעבודה עם מערכי נתונים רפואיים', NULL, NULL, 2, 'להקנות ניסיון מעשי/יישומי בעבודה עם מסדי נתונים רפואיים לצורך בניית תוצר טכנולוגי או מחקרי; להכיר וליישם תהליכי פיתוח ומחקר בעבודה מבוססת נתונים; להטמיע כלים של חשיבה עיצובית לצורך אפיון האתגרים ומציאת פתרונות "בשטח".', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42022', 'טכנולוגיות רפואיות דיגיטליות', 'עיבוד תמונות ביו-רפואיות', NULL, NULL, 2.5, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('42023', 'טכנולוגיות רפואיות דיגיטליות', 'רפואה בעידן הגנומי: הישגים, תקוות וסיכונים', NULL, NULL, 2, 'הקורס נועד לחשוף את הסטודנטים לעולם עיבוד התמונה והראייה הממוחשבת – הכרות עם מושגי יסוד מהתחום ועם אלגוריתמים יסודיים – בדגש על תמונות ביו-רפואיות.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('99105', 'טכנולוגיות רפואיות דיגיטליות', 'כריית נתונים מתקדמת', NULL, NULL, 3, 'להכיר לסטודנטים נושאים מתקדמים מתחום כריית הנתונים, בזיקה ללמידת מכונה ולמידה עמוקה.', 'https://www.hit.ac.il/students/regulations-newsletters/yedion-dmt2025-2026/'),
  ('30052', 'עיצוב פנים', 'סמינר פרויקט גמר', NULL, NULL, 4, NULL, 'https://www.hit.ac.il/students/regulations-newsletters/yedion-design/'),
